      <div class="footer-inner">
        <p>&copy; 2026 Northline Supply Co.</p>
        <nav class="footer-nav" aria-label="Footer">
          <ul>
            <li><a href="#featured-products">Products</a></li>
            <li><a href="#deals">Deals</a></li>
            <li><a href="#editorial">Journal</a></li>
          </ul>
        </nav>
      </div>
    </footer>

    <div class="status" id="status-message" aria-live="polite" aria-atomic="true"></div>

    <script>
      const cartCount = document.querySelector("#cart-count");
      const statusMessage = document.querySelector("#status-message");
      const newsletterForm = document.querySelector("#newsletter-form");
      const emailInput = document.querySelector("#email");
      let cartItems = 0;

      function announce(message) {
        statusMessage.textContent = message;
      }

      document.querySelectorAll(".add-to-cart").forEach((button) => {
        button.addEventListener("click", () => {
          cartItems += 1;
          cartCount.textContent = String(cartItems);
          announce(`${button.dataset.product} added to cart. Cart now has ${cartItems} item${cartItems === 1 ? "" : "s"}.`);
        });
      });

      document.querySelectorAll(".copy-code").forEach((button) => {
        button.addEventListener("click", async () => {
          const code = button.dataset.code;

          if (navigator.clipboard && window.isSecureContext) {
            await navigator.clipboard.writeText(code);
            announce(`Deal code ${code} copied.`);
          } else {
            announce(`Deal code ${code} is ready to copy.`);
          }
        });
      });

      newsletterForm.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!emailInput.validity.valid) {
          emailInput.setAttribute("aria-invalid", "true");
          announce("Enter a valid email address to join the list.");
          emailInput.focus();
          return;
        }

        emailInput.removeAttribute("aria-invalid");
        newsletterForm.reset();
        announce("Thanks for joining the Northline member list.");
      });
    </script>
