const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

const htmlPath = path.resolve(process.cwd(), 'index.html');
const html = fs.readFileSync(htmlPath, 'utf8');

async function runAxe(page, name) {
  const results = await page.evaluate(async () => window.axe.run());
  return {
    name,
    wcag: results.violations
      .filter((v) => !v.tags.includes('best-practice'))
      .map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
    bp: results.violations
      .filter((v) => v.tags.includes('best-practice'))
      .map((v) => ({ id: v.id, targets: v.nodes.map((n) => n.target) })),
  };
}

(async () => {
  const browser = await chromium.launch();
  const scenarios = [];

  for (const viewport of [
    { width: 1366, height: 900, name: 'desktop-initial' },
    { width: 320, height: 900, name: 'mobile-320-initial' },
  ]) {
    const page = await browser.newPage({ viewport });
    await page.setContent(html, { waitUntil: 'load' });
    await page.addScriptTag({ content: axe.source });
    scenarios.push(await runAxe(page, viewport.name));
    await page.close();
  }

  const page = await browser.newPage({ viewport: { width: 1366, height: 900 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  await page.click('button[aria-label="Add to cart: Meteor Shell"]');
  await page.click('button.copy-code');
  await page.click('button[type="submit"]');
  scenarios.push(await runAxe(page, 'after-interactions-invalid-email'));
  await page.fill('#email', 'shopper@example.com');
  await page.click('button[type="submit"]');
  scenarios.push(await runAxe(page, 'after-valid-newsletter-submit'));
  await page.close();

  await browser.close();

  const failures = scenarios.flatMap((scenario) =>
    scenario.wcag.map((violation) => ({ scenario: scenario.name, ...violation }))
  );
  const warnings = scenarios.flatMap((scenario) =>
    scenario.bp.map((violation) => ({ scenario: scenario.name, ...violation }))
  );

  console.log(JSON.stringify({ failures, warnings }));
  process.exit(failures.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
